from torch.utils.cpp_extension import load_inline

# ------------------- CUDA kernel source -------------------
cuda_source = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

template <typename scalar_t>
__global__ void max_reduce_kernel(const scalar_t* __restrict__ input,
                                  scalar_t* __restrict__ output,
                                  int outer,
                                  int reduction,
                                  int inner) {
    int o = blockIdx.x * blockDim.x + threadIdx.x;   // index over outer dimensions
    int i = blockIdx.y * blockDim.y + threadIdx.y;   // index over inner dimensions
    if (o >= outer || i >= inner) return;

    // linear offset of the first element in the reduction axis
    int base = (o * reduction) * inner + i;

    // start with first element (convert half -> float for stable max)
    float max_val = __half2float(input[base]);

    // iterate over the reduction axis
    #pragma unroll
    for (int r = 1; r < reduction; ++r) {
        float val = __half2float(input[base + r * inner]);
        if (val > max_val) max_val = val;
    }

    // write back as half
    output[o * inner + i] = __float2half(max_val);
}

// ----------------------------------------------------------------
// Python‑exposed entry point
torch::Tensor max_reduce_cuda(torch::Tensor input, int64_t dim) {
    // input is assumed to be contiguous and of type Half
    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(input.dtype() == torch::kHalf, "input must be fp16");

    const auto sizes = input.sizes();
    int64_t outer = 1;
    int64_t inner = 1;
    int64_t reduction = sizes[dim];

    for (int i = 0; i < dim; ++i) outer *= sizes[i];
    for (int i = dim + 1; i < (int)sizes.size(); ++i) inner *= sizes[i];

    // shape of output = input shape with `dim` removed
    auto out_sizes = sizes.vec();
    out_sizes.erase(out_sizes.begin() + dim);
    auto output = torch::empty(out_sizes, input.options());

    const dim3 block(128, 8);
    const dim3 grid((outer + block.x - 1) / block.x,
                    (inner + block.y - 1) / block.y);

    AT_DISPATCH_HALF_TYPES(input.scalar_type(), "max_reduce_cuda", ([&] {
        max_reduce_kernel<scalar_t><<<grid, block>>>(
            input.data_ptr<scalar_t>(),
            output.data_ptr<scalar_t>(),
            static_cast<int>(outer),
            static_cast<int>(reduction),
            static_cast<int>(inner));
    }));

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        printf("CUDA error in max_reduce_cuda: %s\\n", cudaGetErrorString(err));
    }

    return output;
}
'''

# ------------------- Compile the extension -------------------
max_reduce_mod = load_inline(name='max_reduce_ext',
                             cpp_sources='',
                             cuda_sources=cuda_source,
                             functions=['max_reduce_cuda'],
                             verbose=False)

# ------------------- Model using the custom kernel ----------
class ModelNew(torch.nn.Module):
    """
    Drop‑in replacement for the reference Model.
    Performs a max reduction over the user‑specified dimension using
    a custom CUDA kernel (fp16 input & output).
    """
    def __init__(self, dim: int):
        super().__init__()
        self.dim = dim

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Ensure tensor is on CUDA and fp16 (the harness is expected to provide this,
        # but we cast defensively)
        if not x.is_cuda:
            x = x.cuda()
        if x.dtype != torch.float16:
            x = x.to(torch.float16)
        return max_reduce_mod.max_reduce_cuda(x, self.dim)
